definition.script:
pipeline {
  agent any

  tools {
    nodejs 'node25'
  }

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '15'))
    timeout(time: 20, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/workforce-pay-bill-p.git'
      }
    }

    stage('Install') {
      steps {
        sh 'npm ci --no-audit --no-fund'
      }
    }

    stage('Build') {
      steps {
        sh 'NODE_OPTIONS=--max-old-space-size=2048 npm run build'
      }
    }
  }

  post {
    always { cleanWs() }
  }
}
